(()=>{
'use strict';
// Pauling values: NIH PubChem periodic-table electronegativity dataset.
const atoms=[{"s": "H", "name": "Hydrogen", "en": 2.2, "row": 1, "col": 1, "z": 1}, {"s": "He", "name": "Helium", "en": null, "row": 1, "col": 8, "z": 2}, {"s": "Li", "name": "Lithium", "en": 0.98, "row": 2, "col": 1, "z": 3}, {"s": "Be", "name": "Beryllium", "en": 1.57, "row": 2, "col": 2, "z": 4}, {"s": "B", "name": "Boron", "en": 2.04, "row": 2, "col": 3, "z": 5}, {"s": "C", "name": "Carbon", "en": 2.55, "row": 2, "col": 4, "z": 6}, {"s": "N", "name": "Nitrogen", "en": 3.04, "row": 2, "col": 5, "z": 7}, {"s": "O", "name": "Oxygen", "en": 3.44, "row": 2, "col": 6, "z": 8}, {"s": "F", "name": "Fluorine", "en": 3.98, "row": 2, "col": 7, "z": 9}, {"s": "Ne", "name": "Neon", "en": null, "row": 2, "col": 8, "z": 10}, {"s": "Na", "name": "Sodium", "en": 0.93, "row": 3, "col": 1, "z": 11}, {"s": "Mg", "name": "Magnesium", "en": 1.31, "row": 3, "col": 2, "z": 12}, {"s": "Al", "name": "Aluminium", "en": 1.61, "row": 3, "col": 3, "z": 13}, {"s": "Si", "name": "Silicon", "en": 1.9, "row": 3, "col": 4, "z": 14}, {"s": "P", "name": "Phosphorus", "en": 2.19, "row": 3, "col": 5, "z": 15}, {"s": "S", "name": "Sulfur", "en": 2.58, "row": 3, "col": 6, "z": 16}, {"s": "Cl", "name": "Chlorine", "en": 3.16, "row": 3, "col": 7, "z": 17}, {"s": "Ar", "name": "Argon", "en": null, "row": 3, "col": 8, "z": 18}];
function polarityArrow(delta,left,right){
 if(Math.abs(delta)<.001)return '';
 const direction=delta>0?1:-1,tail=360-direction*75,head=360+direction*75;
 return `<g class="eg-dipole" role="img" aria-label="Bond dipole points from ${delta>0?left:right}, partially positive, towards ${delta>0?right:left}, partially negative"><title>Bond polarity</title><path d="M ${tail-direction*10} 337 H ${head} M ${head-direction*12} 327 L ${head} 337 L ${head-direction*12} 347 M ${tail} 327 V 347"/></g>`;
}
class BondPlay{constructor(){this.left=0;this.right=16;this.x=this.target;this.info=false;this.charges=false}get a(){return atoms[this.left]}get b(){return atoms[this.right]}get difference(){return this.b.en-this.a.en}get target(){return 360+Math.max(-125,Math.min(125,this.difference*65))}pull(x){this.x=Math.max(235,Math.min(485,x))}reset(){this.x=this.target}}
if(typeof module!=='undefined'&&module.exports)module.exports={BondPlay,atoms,polarityArrow};if(typeof document==='undefined')return;const root=document.getElementById('electronegativity-game');if(!root)return;const game=new BondPlay(),el=id=>document.getElementById('eg-'+id);let frame=0,drag=null,velocity=0;
for(const id of ['left','right'])el(id).innerHTML=atoms.map((a,i)=>`<option value="${i}" ${a.en===null?'disabled':''}>${a.name} (${a.s})</option>`).join('');
function position(){el('cloud').setAttribute('aria-valuenow',String(Math.round(game.x)));el('cloud').setAttribute('transform',`translate(${game.x} 210)`)}
function stop(){cancelAnimationFrame(frame);frame=0;velocity=0}
function settle(){stop();if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){game.reset();position();return}let last=0;function step(time){const dt=last?Math.min(2,(time-last)/16.667):1;last=time;velocity+=(game.target-game.x)*.065*dt;velocity*=Math.pow(.77,dt);game.x+=velocity*dt;position();if(Math.abs(game.target-game.x)<.15&&Math.abs(velocity)<.15){game.reset();position();frame=0}else frame=requestAnimationFrame(step)}frame=requestAnimationFrame(step)}
function render(){for(const side of ['left','right']){const a=atoms[game[side]];el(side+'-trigger').textContent=a.name+' ('+a.s+')';el(side+'-table').querySelectorAll('[data-atom]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.atom)===game[side])))}el('left').value=String(game.left);el('right').value=String(game.right);el('info').setAttribute('aria-pressed',String(game.info));el('info').textContent=game.info?'Hide data':'Show data';el('charges').setAttribute('aria-pressed',String(game.charges));el('charges').textContent=game.charges?'Hide partial charges':'Show partial charges';el('details').hidden=!game.info;el('a-value').textContent=game.a.s+' · '+game.a.en.toFixed(2);el('b-value').textContent=game.b.s+' · '+game.b.en.toFixed(2);el('difference').textContent=Math.abs(game.difference).toFixed(2);
 const delta=game.difference;el('balance').textContent=Math.abs(delta)<.001?'Shared equally':'Electron density drawn toward '+(delta>0?game.b.s:game.a.s);
 el('diagram').innerHTML=`<defs><radialGradient id="eg-density"><stop offset="0" stop-color="#88b16b" stop-opacity=".65"/><stop offset=".55" stop-color="#a7c78e" stop-opacity=".4"/><stop offset="1" stop-color="#c9dfb5" stop-opacity="0"/></radialGradient></defs><line x1="200" x2="520" y1="210" y2="210" class="eg-bond"/><line x1="360" x2="360" y1="115" y2="300" class="eg-midline"/><g id="eg-cloud" class="eg-cloud" transform="translate(${game.x} 210)" role="slider" tabindex="0" aria-label="Shared electron cloud" aria-valuemin="235" aria-valuemax="485" aria-valuenow="${Math.round(game.x)}"><ellipse rx="155" ry="90" fill="url(#eg-density)"/><ellipse rx="60" ry="50" fill="transparent"/><circle cx="-8" r="6" class="eg-electron"/><circle cx="8" r="6" class="eg-electron"/></g><g class="eg-atom"><circle cx="200" cy="210" r="43"/><text x="200" y="222">${game.a.s}</text></g><g class="eg-atom"><circle cx="520" cy="210" r="43"/><text x="520" y="222">${game.b.s}</text></g>${polarityArrow(delta,game.a.s,game.b.s)}${game.charges&&delta!==0?`<text x="230" y="151" class="${delta>0?'eg-positive':'eg-negative'}">${delta>0?'δ+':'δ−'}</text><text x="550" y="151" class="${delta>0?'eg-negative':'eg-positive'}">${delta>0?'δ−':'δ+'}</text>`:''}`;document.dispatchEvent(new Event('chemi-controls-sync'));
}
function change(){stop();drag=null;game.reset();render()}
el('left').addEventListener('change',e=>{game.left=Number(e.target.value);change()});el('right').addEventListener('change',e=>{game.right=Number(e.target.value);change()});el('swap').addEventListener('click',()=>{[game.left,game.right]=[game.right,game.left];change()});el('reset').addEventListener('click',change);el('info').addEventListener('click',()=>{game.info=!game.info;render()});el('charges').addEventListener('click',()=>{game.charges=!game.charges;render()});
const svg=el('diagram');function point(e){const p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform(svg.getScreenCTM().inverse())}
svg.addEventListener('pointerdown',e=>{if(e.button!==0||!e.target.closest('#eg-cloud'))return;e.preventDefault();stop();const p=point(e);drag={id:e.pointerId,offset:p.x-game.x};svg.setPointerCapture(e.pointerId)});
svg.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;e.preventDefault();game.pull(point(e).x-drag.offset);position()});
function release(e){if(!drag||e.pointerId!==drag.id)return;drag=null;if(svg.hasPointerCapture(e.pointerId))svg.releasePointerCapture(e.pointerId);settle()}
svg.addEventListener('pointerup',release);svg.addEventListener('pointercancel',release);svg.addEventListener('keydown',e=>{if(!e.target.closest('#eg-cloud'))return;if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();stop();game.pull(game.x+(e.key==='ArrowLeft'?-18:18));position()}if(e.key==='Enter'||e.key===' '||e.key==='Escape'){e.preventDefault();settle()}});svg.addEventListener('keyup',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight')settle()});

function closeTables(){for(const side of ['left','right']){el(side+'-table').hidden=true;el(side+'-trigger').setAttribute('aria-expanded','false')}}
for(const side of ['left','right']){
 const panel=el(side+'-table'),trigger=el(side+'-trigger');
 panel.innerHTML='<div class="eg-ptable-grid">'+[1,2,13,14,15,16,17,18].map((group,i)=>`<span class="eg-group" style="grid-column:${i+1};grid-row:1">${group}</span>`).join('')+atoms.map((a,i)=>`<button type="button" data-atom="${i}" class="eg-element" style="grid-column:${a.col};grid-row:${a.row+1};--element-fill:${a.en===null?'#eff2e9':`hsl(94 30% ${94-(a.en-.9)*10}%)`}" ${a.en===null?'disabled':''} aria-label="${a.name}, atomic number ${a.z}${a.en===null?', no standard Pauling value':''}" title="${a.name}${a.en===null?' — no standard Pauling value':''}" aria-pressed="false"><small>${a.z}</small><strong>${a.s}</strong></button>`).join('')+'</div><p class="eg-table-note">He, Ne, Ar: no standard Pauling value.</p>';
 trigger.addEventListener('click',()=>{const opening=panel.hidden;closeTables();if(opening){panel.hidden=false;trigger.setAttribute('aria-expanded','true');panel.querySelector('[data-atom="'+game[side]+'"]').focus()}});
 panel.addEventListener('click',e=>{const b=e.target.closest('[data-atom]');if(!b||b.disabled)return;game[side]=Number(b.dataset.atom);closeTables();change();trigger.focus()});
 panel.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();closeTables();trigger.focus();return}const b=e.target.closest('[data-atom]');if(!b||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const current=atoms[Number(b.dataset.atom)];const horizontal=e.key==='ArrowLeft'||e.key==='ArrowRight',direction=e.key==='ArrowLeft'||e.key==='ArrowUp'?-1:1;const candidates=atoms.map((a,i)=>({...a,i})).filter(a=>a.en!==null&&(horizontal?a.row===current.row&&(a.col-current.col)*direction>0:a.col===current.col&&(a.row-current.row)*direction>0));candidates.sort((a,b)=>horizontal?Math.abs(a.col-current.col)-Math.abs(b.col-current.col):Math.abs(a.row-current.row)-Math.abs(b.row-current.row));if(candidates.length)panel.querySelector('[data-atom="'+candidates[0].i+'"]').focus()});
 panel.addEventListener('focusout',e=>{if(!panel.contains(e.relatedTarget)&&e.relatedTarget!==trigger)closeTables()});
}
document.addEventListener('pointerdown',e=>{if(!e.target.closest('.eg-periodic-picker'))closeTables()});window.addEventListener('hashchange',closeTables);

window.addEventListener('hashchange',()=>{stop();drag=null;game.reset();position()});render();
})();
